window.Utils={getSmartPath:(fileName,category='DEFAULT')=>{if(!fileName)return '';if(fileName.includes('://')||fileName.startsWith('data:'))return fileName;const projConfig=typeof PROJECT_CONFIG!=='undefined'?PROJECT_CONFIG.paths:{};const cvConfig=window.cvData&&window.cvData.config?window.cvData.config:{};let basePath='assets/images/';if(category==='PORTFOLIO')basePath=cvConfig.portfolioPath||projConfig.DEFAULT||basePath;else if(category==='PROFILE')basePath=cvConfig.profilePath||basePath;else if(category==='ART')basePath='../assets/images/ilustraciones/';else if(category==='DESIGN')basePath='../assets/images/design/';else if(category==='DEV')basePath='../assets/images/dev/';else if(projConfig[category])basePath=projConfig[category];else basePath=projConfig.DEFAULT||basePath;return `${basePath}${fileName}`;},handleImgError:function(img){if(img.dataset.dead==='true')return;console.warn('Imagen no encontrada:',img.src);img.dataset.dead='true';img.style.display='none';},copyText:(text,element=null)=>{if(navigator.clipboard){navigator.clipboard .writeText(text).then(()=>{if(element){const originalText=element.innerText;const originalColor=element.style.color;element.innerText='¡COPIADO!';element.style.color='#2ecc71';setTimeout(()=>{element.innerText=originalText;element.style.color=originalColor;},1500);}const toast=document.getElementById('toast');if(toast){toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2000);}}).catch((err)=>console.error('Error copy:',err));}},formatTags:(tags,limit=2)=>{return tags?.slice(0,limit).join(' / ').toUpperCase()||'PROJECT';},initIcons:()=>{if(typeof lucide!=='undefined')lucide.createIcons();},stripHtmlToText:(html)=>{if(!html)return '';let t=html.replace(/<br\s*\/?>/gi,' ');t=t.replace(/<[^>]+>/g,' ');t=t.replace(/\s+/g,' ').trim();return t;},};